/* gap8/main.c: run ZOI on the GAP8 cluster and count cycles per stage.
 *
 * Inputs: the frames in trace_data.h (poses and detector boxes of a recorded
 * flight, generated by tools/c_port/make_gap8_trace.py). For every frame it runs
 * the detector-frame update, the plans (FLIGHT below) and one navigator step
 * towards the planned target; it checks the frame's first plan against the
 * Python one stored in the trace and prints the cycles of each stage.
 *
 * Plans of a frame. The first is made from the frame's pose right after the
 * frame, with that frame's desk cells in the planner's table map: this is where
 * Python took the decision stored in the trace, and "plans equal to Python"
 * checks it. With FLIGHT=1 a frame can have a second plan (about one detector
 * period in eight in the recorded flights): in flight it happens on arrival at
 * the first plan's target, at a later control step, after zoi_control_step has
 * cleared frame_desk_valid. So, whatever ZOI_IG_CACHE, every later plan of a
 * frame is made with frame_desk_valid = 0 from the arrival pose on the previous
 * plan's target (cell centre, target yaw). The trace has no Python decision for
 * it, so it is not checked here (host/replay_test.c runs the same sequence,
 * cache on and off). The last line, "plan decisions hash", covers every plan (candidate, rate and
 * T bits): equal between builds that must take the same decisions.
 *
 * The fabric controller only starts the cluster; everything runs on the cluster:
 * core 0 runs the algorithm, and the parallel kernels (evidence, beliefs,
 * planner IG and flight times) are spread over NB_CORES cores with pi_cl_team_fork.
 * A self-test at start-up prints which cores actually run a forked kernel.
 *
 * Build options (gap8/Makefile): NB_CORES (1..8), ZOI_REFERENCE_KERNELS (1
 * faithful, 0 optimised), CL_FREQ_MHZ (only to convert cycles to ms),
 * MAX_FRAMES (0: all frames of the trace), FLIGHT (0: a plan every frame, the
 * worst case; 1: plans on the frames, and as many times, as the recorded flight),
 * ZOI_PLANNER_PRUNING (0, 1, 2), ZOI_IG_CACHE (0, 1).
 *
 * Written against the PMSIS API of the GAP SDK. See ../README.md.
 */
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "pmsis.h"

#include "trace_data.h"
#include "zoi.h"

#ifndef NB_CORES
#define NB_CORES 8
#endif
#ifndef CL_FREQ_MHZ
#define CL_FREQ_MHZ 260
#endif
#ifndef MAX_FRAMES
#define MAX_FRAMES 0
#endif
/* 0: a plan on every frame (worst case). 1: plans as in the recorded flight
 * (TRACE_REPLANS[f] plans after frame f: 0, 1 or 2, from the flight's replan counter). */
#ifndef FLIGHT
#define FLIGHT 0
#endif
/* MobileNetV2-SSD on GAP8 (DORY, INT8), measured latency, in hundredths of ms. */
#define MOBILENET_MS_X100 41036u

#if TRACE_GRID_N != ZOI_GRID_N
#error "trace_data.h was generated for another (rho, theta) grid size"
#endif

/* In L2 (globals of a PMSIS program go to L2 by default). */
static zoi_state_t st;

/* ---- Parallel kernels on the cluster ---------------------------------- */

static zoi_kernel_fn g_fn;
static void *g_arg;
/* Chunks run by each core since start-up: all NB_CORES entries must grow. */
static volatile uint32_t chunks_per_core[8];

static void team_entry(void *arg)
{
    (void)arg;
    const int core = (int)pi_core_id();
    if (core >= 0 && core < 8)
        chunks_per_core[core]++;
    g_fn(g_arg, core, NB_CORES);
}

static void cluster_fork(zoi_kernel_fn fn, void *arg)
{
    g_fn = fn;
    g_arg = arg;
    pi_cl_team_fork(NB_CORES, team_entry, NULL); /* returns when every core is done */
}

/* Fork self-test: every core that runs the kernel marks itself. */
static volatile int fork_seen[8];

static void fork_probe(void *arg, int core, int ncores)
{
    (void)arg;
    (void)ncores;
    if (core >= 0 && core < 8)
        fork_seen[core] = 1;
}

static void fork_self_test(void)
{
    for (int c = 0; c < 8; c++)
        fork_seen[c] = 0;
    zoi_fork(fork_probe, NULL);
    printf("fork self-test: NB_CORES=%d, zoi_fork is %s, cluster reports %d cores, cores that ran:", NB_CORES,
           zoi_fork == cluster_fork ? "the cluster fork" : "SERIAL (core 0 only)", (int)pi_cl_cluster_nb_cores());
    int n = 0;
    for (int c = 0; c < 8; c++)
        if (fork_seen[c]) {
            printf(" %d", c);
            n++;
        }
    printf("  -> %s\n", n == NB_CORES ? "OK" : "NOT ALL CORES RAN");
}

/* ---- Cycle counting --------------------------------------------------- */

static uint32_t stage_start[ZOI_N_STAGES];
static uint32_t frame_cycles[ZOI_N_STAGES];

static void profile(zoi_stage_t stage, int start)
{
    const uint32_t now = (uint32_t)pi_perf_read(PI_PERF_CYCLES);
    if (start)
        stage_start[stage] = now;
    else
        frame_cycles[stage] += now - stage_start[stage]; /* unsigned: wrap-safe */
}

/* Components: belief update = geometry + update + beliefs; planner = IG + T; navigator. */
enum { C_BELIEF = 0, C_PLANNER, C_NAVIGATOR, N_COMP };
static const char *COMP_NAMES[N_COMP] = {"belief update", "planner", "navigator"};

static uint32_t ms_x100(uint64_t cycles) /* hundredths of ms at CL_FREQ_MHZ */
{
    return (uint32_t)((cycles + (uint64_t)CL_FREQ_MHZ * 5u) / ((uint64_t)CL_FREQ_MHZ * 10u));
}

/* FNV-1a over the decisions of every plan: candidate, rate and T bits. */
static uint32_t plan_hash = 2166136261u;

static void hash_word(uint32_t w)
{
    for (int i = 0; i < 4; i++) {
        plan_hash ^= (w >> (8 * i)) & 0xffu;
        plan_hash *= 16777619u;
    }
}

static void hash_plan(int k)
{
    const float rate = st.cand_ig[k] / st.cand_T[k];
    uint32_t r, t;
    memcpy(&r, &rate, sizeof(r));
    memcpy(&t, &st.cand_T[k], sizeof(t));
    hash_word((uint32_t)k);
    hash_word(r);
    hash_word(t);
}

static void print_x100(uint32_t v)
{
    printf("%u.%02u", (unsigned)(v / 100u), (unsigned)(v % 100u));
}

static void cluster_main(void *arg)
{
    (void)arg;
    pi_perf_conf(1 << PI_PERF_CYCLES);
    pi_perf_reset();
    pi_perf_start();

    if (NB_CORES > 1)
        zoi_fork = cluster_fork;

    zoi_config_t cfg;
    zoi_config_default(&cfg, TRACE_ENV, TRACE_DET);
    cfg.recall = TRACE_PARAMS[0];
    cfg.class_accuracy = TRACE_PARAMS[1];
    cfg.false_alarm = TRACE_PARAMS[2];
    cfg.table_context = TRACE_TABLE_CONTEXT;
    if (cfg.table_context) {
        cfg.desk_recall = TRACE_PARAMS[3];
        cfg.desk_false_alarm = TRACE_PARAMS[4];
        cfg.p_on_table = TRACE_PARAMS[5];
    }

    const uint32_t t_init = (uint32_t)pi_perf_read(PI_PERF_CYCLES);
    const int rc = zoi_init(&st, &cfg);
    const uint32_t init_cycles = (uint32_t)pi_perf_read(PI_PERF_CYCLES) - t_init;
    if (rc != 0) {
        printf("zoi_init failed (%d)\n", rc);
        return;
    }
    const int n_frames = (MAX_FRAMES > 0 && MAX_FRAMES < TRACE_N_FRAMES) ? MAX_FRAMES : TRACE_N_FRAMES;
    printf("ZOI on GAP8: %d cores, %s kernels, planner pruning %d, IG cache %d, %s, %d frames, state %u B, "
           "grid %d points, init %u cycles\n",
           NB_CORES, ZOI_REFERENCE_KERNELS ? "reference" : "optimised", ZOI_PLANNER_PRUNING, ZOI_IG_CACHE,
           FLIGHT ? "plans as in the recorded flight" : "a plan every frame", n_frames,
           (unsigned)sizeof(zoi_state_t),
           st.n_grid, (unsigned)init_cycles);
    fork_self_test();
    zoi_profile = profile;

    printf("frame;geometry;update;beliefs;planner_IG;planner_T;navigator;belief_update;planner;total;"
           "seen_cells;active_points;IG_cands;T_cands;plans;plan_ok;plan_call_max;IG_cands_all\n");

    uint64_t comp_total[N_COMP] = {0, 0, 0};
    uint32_t comp_max[N_COMP] = {0, 0, 0};
    int plans_ok = 0, plans_checked = 0, plans_total = 0;
    for (int f = 0; f < n_frames; f++) {
        for (int s = 0; s < ZOI_N_STAGES; s++)
            frame_cycles[s] = 0;
        zoi_perception_frame(&st, &TRACE_POSE[f], &TRACE_BOXES[TRACE_BOX_START[f]], TRACE_BOX_COUNT[f]);
        int n_plans = FLIGHT ? TRACE_REPLANS[f] : 1;
        if (n_plans < 0)
            n_plans = 1; /* not recorded: count one plan */
        int ok = -1; /* -1: no plan this frame */
        /* Cycles of the costliest plan call of the frame (belief refresh + IG + T: the
         * beliefs are recomputed only when the planner reads them) and the exact IGs
         * of all its plans; the IG_cands column has the last plan's only. */
        uint32_t plan_call_max = 0;
        int ig_all = 0;
        zoi_pose_t pose = TRACE_POSE[f];
        for (int p = 0; p < n_plans; p++) {
            /* The first plan from the frame's pose, where the Python decision of the
             * trace was taken; a later one as in flight (see the top of the file):
             * a later control step, from the arrival pose on the previous target. */
            if (p > 0) {
                st.frame_desk_valid = 0;
                pose.x = cfg.min_x + ((float)(st.target_cell % ZOI_COLS) + 0.5f) * cfg.cell_size;
                pose.y = cfg.min_y + ((float)(st.target_cell / ZOI_COLS) + 0.5f) * cfg.cell_size;
                pose.yaw = st.target_yaw;
            }
            const uint32_t before =
                frame_cycles[ZOI_STAGE_BELIEFS] + frame_cycles[ZOI_STAGE_IG] + frame_cycles[ZOI_STAGE_TIME];
            const int k = zoi_plan(&st, &pose);
            hash_plan(k);
            const uint32_t call = frame_cycles[ZOI_STAGE_BELIEFS] + frame_cycles[ZOI_STAGE_IG] +
                                  frame_cycles[ZOI_STAGE_TIME] - before;
            if (call > plan_call_max)
                plan_call_max = call;
            ig_all += st.n_ig_evals;
            if (p == 0) {
                ok = (k == TRACE_PLAN[f]);
                plans_ok += ok;
                plans_checked++;
            }
            st.has_target = 1;
            st.target_cell = k / ZOI_N_YAW;
            st.target_yaw_index = k % ZOI_N_YAW;
            st.target_yaw = st.yaw_options[st.target_yaw_index];
        }
        plans_total += n_plans;
        /* One navigator step towards the current target. */
        zoi_command_t cmd;
        zoi_navigator_step(&st, &TRACE_POSE[f], &cmd);

        const uint32_t *c = frame_cycles;
        const uint32_t comp[N_COMP] = {
            c[ZOI_STAGE_GEOMETRY] + c[ZOI_STAGE_UPDATE] + c[ZOI_STAGE_BELIEFS],
            c[ZOI_STAGE_IG] + c[ZOI_STAGE_TIME],
            c[ZOI_STAGE_NAVIGATOR],
        };
        for (int i = 0; i < N_COMP; i++) {
            comp_total[i] += comp[i];
            if (comp[i] > comp_max[i])
                comp_max[i] = comp[i];
        }
        printf("%d;%u;%u;%u;%u;%u;%u;%u;%u;%u;%d;%d;%d;%d;%d;%d;%u;%d\n", f, (unsigned)c[ZOI_STAGE_GEOMETRY],
               (unsigned)c[ZOI_STAGE_UPDATE], (unsigned)c[ZOI_STAGE_BELIEFS], (unsigned)c[ZOI_STAGE_IG],
               (unsigned)c[ZOI_STAGE_TIME], (unsigned)c[ZOI_STAGE_NAVIGATOR], (unsigned)comp[C_BELIEF],
               (unsigned)comp[C_PLANNER], (unsigned)(comp[0] + comp[1] + comp[2]), st.n_seen, st.n_active,
               n_plans ? st.n_ig_evals : 0, n_plans ? st.n_T_evals : 0, n_plans, ok, (unsigned)plan_call_max,
               ig_all);
    }

    /* Summary per component: mean and max per frame, ms at CL_FREQ_MHZ, share of the
     * total with MobileNetV2-SSD. */
    uint32_t mean_ms[N_COMP], total_ms = MOBILENET_MS_X100;
    for (int i = 0; i < N_COMP; i++) {
        mean_ms[i] = ms_x100(comp_total[i] / (uint64_t)n_frames);
        total_ms += mean_ms[i];
    }
    printf("\ncomponent       mean cycles   max cycles   mean ms   max ms   %% of total   (@%d MHz, %d plans in %d frames)\n",
           CL_FREQ_MHZ, plans_total, n_frames);
    for (int i = 0; i < N_COMP; i++) {
        printf("%-14s %12u %12u   ", COMP_NAMES[i], (unsigned)(comp_total[i] / (uint64_t)n_frames),
               (unsigned)comp_max[i]);
        print_x100(mean_ms[i]);
        printf("   ");
        print_x100(ms_x100(comp_max[i]));
        printf("   ");
        print_x100((uint32_t)((uint64_t)mean_ms[i] * 10000u / total_ms));
        printf("\n");
    }
    printf("%-14s %12s %12s   ", "MobileNetV2", "", "");
    print_x100(MOBILENET_MS_X100);
    printf("            ");
    print_x100((uint32_t)((uint64_t)MOBILENET_MS_X100 * 10000u / total_ms));
    printf("\n%-14s %12s %12s   ", "total", "", "");
    print_x100(total_ms);
    printf("            (detector period 625 ms)\n");
    printf("chunks run per core:");
    for (int c = 0; c < NB_CORES && c < 8; c++)
        printf(" %u", (unsigned)chunks_per_core[c]);
    printf("\nplan decisions hash: 0x%08x (%d plans)\n", (unsigned)plan_hash, plans_total);
    printf("plans equal to Python: %d / %d\n", plans_ok, plans_checked);
}

/* ---- Fabric controller ------------------------------------------------- */

static void app_main(void)
{
    struct pi_device cluster_dev;
    struct pi_cluster_conf conf;
    struct pi_cluster_task task;

    pi_cluster_conf_init(&conf);
    conf.id = 0;
    pi_open_from_conf(&cluster_dev, &conf);
    if (pi_cluster_open(&cluster_dev)) {
        printf("cluster open failed\n");
        pmsis_exit(-1);
    }
    pi_cluster_task(&task, cluster_main, NULL);
    task.stack_size = 8192;       /* core 0: the algorithm (largest frame ~3 kB) */
    task.slave_stack_size = 2048; /* cores 1..7: the kernels */
    pi_cluster_send_task_to_cl(&cluster_dev, &task);
    pi_cluster_close(&cluster_dev);
    pmsis_exit(0);
}

int main(void)
{
    return pmsis_kickoff((void *)app_main);
}
